import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable } from 'rxjs';
import { tap } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private apiUrl = '/auth';
  private isLoggedInSubject = new BehaviorSubject<boolean>(false);
  isLoggedIn$ = this.isLoggedInSubject.asObservable();

  constructor(private http: HttpClient) {
    this.checkInitialLoginState();
  }

  public checkInitialLoginState(): void {
    const token = localStorage.getItem('token');
    this.isLoggedInSubject.next(!!token);
  }

  public updateLoginState(isLoggedIn: boolean): void {
    this.isLoggedInSubject.next(isLoggedIn);
  }

  public validateToken(token: string): Observable<{ valid: boolean }> {
    return this.http.post<{ valid: boolean }>(`${this.apiUrl}/validate-token`, { token }).pipe(
      tap((response) => {
        this.updateLoginState(response.valid);
      })
    );
  }

  public login(token: string): void {
    localStorage.setItem('token', token);
    this.updateLoginState(true);
  }

  public clearToken(): void {
    localStorage.removeItem('token');
    this.updateLoginState(false);
  }
}

import { Component, DestroyRef, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { MaterialModule } from '../../shared/material.module';
import { UserService } from '../../core/service/user.service';
import { Register } from '../../core/models/Register';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import {Router} from '@angular/router';
import {AuthService} from '../../core/service/auth.service';

@Component({
  selector: 'app-register',
  imports: [CommonModule, MaterialModule],
  templateUrl: './register.component.html',
  standalone: true,
  styleUrl: './register.component.css'
})
export class RegisterComponent implements OnInit {
  registerForm: FormGroup = new FormGroup({});
  submitted: boolean = false;
  isLoading = false;
  errorMessage: string | null = null;
  successMessage: string | null = null;
  isLoggedIn: boolean = false;

  constructor(
    private userService: UserService,
    private router: Router,
    private formBuilder: FormBuilder,
    private destroyRef: DestroyRef,
    private authService: AuthService,
  ) {}

  ngOnInit() {
    this.authService.isLoggedIn$.subscribe((isLoggedIn: boolean) => {
      this.isLoggedIn = isLoggedIn;

      if (this.isLoggedIn) {
        this.router.navigate(['/students/list']);
      }
    });

    this.registerForm = this.formBuilder.group(
      {
        firstName: ['', Validators.required],
        lastName: ['', Validators.required],
        login: ['', Validators.required],
        password: ['', Validators.required]
      },
    );
  }

  get form() {
    return this.registerForm.controls;
  }

  onSubmit(): void {
    this.submitted = true;
    this.isLoading = true;

    if (this.registerForm.invalid) {
      this.isLoading = false;
      return;
    }

    this.errorMessage = null;
    this.successMessage = null;

    const registerUser: Register = {
      firstName: this.registerForm.get('firstName')?.value,
      lastName: this.registerForm.get('lastName')?.value,
      login: this.registerForm.get('login')?.value,
      password: this.registerForm.get('password')?.value
    };

    this.userService.register(registerUser)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.successMessage = 'User registered successfully!';
          this.isLoading = false;
        },
        error: (err) => {
          this.errorMessage = err.error?.message;
          this.isLoading = false;
        }
      }
    );
  }

  onReset(): void {
    this.submitted = false;
    this.registerForm.reset();
    this.router.navigate(['/']);
  }

  goHome(): void {
    this.router.navigate(['/']);
  }
}
<div class="card m-3">
  <h5 class="card-header">Registration Form</h5>
  <div class="card-body">
    <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
      <div class="form-row">
        <div class="form-group col-6">
          <label>First Name</label>
          <input
            type="text"
            formControlName="firstName"
            class="form-control"
            [ngClass]="{ 'is-invalid': submitted && form['firstName'].errors }"
          />
          @if (submitted && form['firstName'].errors) {
            <div class="invalid-feedback">
              @if (form['firstName'].errors?.['required']) {
                <div>First Name is required</div>
              }
            </div>
          }
        </div>
        <div class="form-group col-6">
          <label>Last Name</label>
          <input
            type="text"
            formControlName="lastName"
            class="form-control"
            [ngClass]="{ 'is-invalid': submitted && form['lastName'].errors }"
          />
          @if (submitted && form['lastName'].errors) {
            <div class="invalid-feedback">
              @if (form['lastName'].errors?.['required']) {
                <div>Last Name is required</div>
              }
            </div>
          }
        </div>
      </div>
      <div class="form-group">
        <label>Login</label>
        <input
          type="text"
          formControlName="login"
          class="form-control"
          [ngClass]="{ 'is-invalid': submitted && form['login'].errors }"
        />
        @if (submitted && form['login'].errors) {
          <div class="invalid-feedback">
            @if (form['login'].errors?.['required']) {
              <div>Login is required</div>
            }
          </div>
        }
      </div>

      <div class="form-group">
        <label>Password</label>
        <input
          type="password"
          formControlName="password"
          class="form-control"
          [ngClass]="{ 'is-invalid': submitted && form['password'].errors }"
        />
        @if (submitted && form['password'].errors) {
          <div class="invalid-feedback">
            @if (form['password'].errors?.['required']) {
              <div>password is required</div>
            }
          </div>
        }
      </div>
      <div class="text-center">
        <button class="btn btn-primary mr-1" type="submit" [disabled]="isLoading || registerForm.invalid">
          <span *ngIf="!isLoading">Register</span>
          <span *ngIf="isLoading" >
            <mat-spinner diameter="25" class="spinner-white"></mat-spinner>
          </span>
        </button>
        <button class="btn btn-secondary" type="reset" (click)="onReset()">
          Cancel
        </button>
      </div>

      <div *ngIf="errorMessage" class="error-message">
        {{ errorMessage }}
      </div>
      <div *ngIf="successMessage" class="success-message">
        {{ successMessage }}
      </div>
    </form>
    <div style="margin-top: 20px;">
      <button class="btn btn-warning" (click)="goHome()">Go Home</button>
    </div>
  </div>
</div>

