import {MatIconButton} from '@angular/material/button';
import {Router} from '@angular/router';

@Component({
  selector: 'app-student-list',
  imports: [
    SidebarComponent,
    MatProgressSpinner,
    MatTable,
    MatColumnDef,
    MatHeaderCell,
    MatCell,
    MatHeaderRow,
    MatRow,
    MatHeaderCellDef,
    MatCellDef,
    NgIf,
    MatHeaderRowDef,
    MatRowDef,
    MatIcon,
    MatIconButton
  ],
  templateUrl: './student-list.component.html',
  styleUrl: './student-list.component.css'
})
export class StudentListComponent {
  students: any[] = [];
  isLoading: boolean = true;
  errorMessage: string | null = null;
  displayedColumns: string[] = ['id', 'lastName', 'firstName', 'actions'];

  constructor(
    private studentService: StudentService,
    private router: Router,
  ) {}

  goToEdit(id: number) {
    this.router.navigate([`/students/edit/`, id]);
  }

  goToDetail(id: number) {
    this.router.navigate([`/students/detail/`, id]);
  }

  goToAdd(): void {
    this.router.navigate([`/students/create/`]);
  }

  deleteStudent(id: number) {
    if (confirm('Voulez-vous vraiment supprimer cet étudiant ?')) {
      this.isLoading = true;
      this.studentService.deleteStudent(id).subscribe({
        next: () => {
          this.loadStudents();
        },
        error: (err: any) => {
          this.errorMessage = "Erreur lors de la suppression de l'étudiant.";
          this.isLoading = false;
        }
      });
    }
  }

  ngOnInit(): void {
    this.loadStudents();
  }

  loadStudents(): void {
    this.isLoading = true;
    this.errorMessage = null;

    this.studentService.getStudents().subscribe({
      next: (data: any) => {
        this.students = data;
        this.isLoading = false;
      },
      error: (err: any) => {
        this.errorMessage = 'Erreur lors de la récupération des étudiants.';
        this.isLoading = false;
        console.error('Erreur:', err);
      }
    });
  }
}
<div class="container">
  <span>
    <h2>List of students</h2>
  </span>

  <div style="text-align: center">
    <button (click)=goToAdd() class="btn btn-primary">Ajouter un étudiant</button>
  </div>

  <div class="card-body" *ngIf="isLoading">
    <div class="text-center">
      <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden"></span>
      </div>
    </div>
  </div>

  <div *ngIf="errorMessage" class="error">
    {{ errorMessage }}
  </div>

  <table *ngIf="!isLoading && !errorMessage" mat-table [dataSource]="students" class="mat-elevation-z8">
    <ng-container matColumnDef="id">
      <th mat-header-cell *matHeaderCellDef>ID</th>
      <td mat-cell *matCellDef="let student">{{ student.id }}</td>
    </ng-container>

    <ng-container matColumnDef="lastName">
      <th mat-header-cell *matHeaderCellDef>Last Name</th>
      <td mat-cell *matCellDef="let student">{{ student.lastName }}</td>
    </ng-container>

    <ng-container matColumnDef="firstName">
      <th mat-header-cell *matHeaderCellDef>First Name</th>
      <td mat-cell *matCellDef="let student">{{ student.firstName }}</td>
    </ng-container>

    <ng-container matColumnDef="actions">
      <th mat-header-cell *matHeaderCellDef>Actions</th>
      <td mat-cell *matCellDef="let student" class="actions-cell">
        <button mat-icon-button color="primary" (click)="goToEdit(student.id); $event.stopPropagation();" aria-label="Éditer">
          <mat-icon>edit</mat-icon>
        </button>
        <button mat-icon-button color="warn" (click)="deleteStudent(student.id); $event.stopPropagation();" aria-label="Supprimer">
          <mat-icon>delete</mat-icon>
        </button>
      </td>
    </ng-container>

    <tr mat-header-row *matHeaderRowDef="displayedColumns"></tr>
    <tr (click)="goToDetail(student.id)" mat-row *matRowDef="let student; columns: displayedColumns;" class="clickable-row"></tr>
  </table>

</div>

import { Injectable } from '@angular/core';
import { CanActivate, Router } from '@angular/router';
import { Observable, of } from 'rxjs';
import {AuthService} from '../service/auth.service';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {
  constructor(private router: Router, private authService: AuthService) {}

  canActivate(): Observable<boolean> {
    const token = localStorage.getItem('token');

    if (!token) {
      this.authService.updateLoginState(false);
      this.authService.clearToken();
      this.router.navigate(['/login']);

      return of(false);
    }

    return of(true);
  }
}

